@dataclass
class ServerArgs:
    mem_fraction_static: float = 0.88
    enable_hybrid_memory_pool: bool = False
    max_running_requests: int = 4096

def create_memory_pool(server_args, model_config):
    if server_args.enable_hybrid_memory_pool:
        return HybridReqToTokenPool(model_config, server_args.mem_fraction_static)
    return ReqToTokenPool(model_config, server_args.mem_fraction_static)

def schedule_prefill(self):
    batch = ScheduleBatch.init_new(self.running_queue, self.req_to_token_pool)
    budget = batch.compute_prefill_token_budget(self.max_prefill_tokens)
    return batch.prepare_for_prefill(budget)

class ScheduleBatch:
    def compute_prefill_token_budget(self, max_prefill_tokens: int) -> PrefillBudget:
        available = max_prefill_tokens - self.cached_prefix_tokens
        return PrefillBudget(input_tokens=max(available, 0), chunked=self.has_chunked_req())

class BlockSparseAttentionBackend(AttentionBackend):
    name = "block_sparse"
    def forward_extend(self, q, k, v, block_mask):
        return block_sparse_attention(q, k, v, block_mask)
